            if (menuItem2.getItemId() == R.id.menu_adblock) {
                menuItem2.setVisible(false);
            } else{
                Toast.makeText(getContext(), "Error: Adblock menu item ID wrong", Toast.LENGTH_SHORT).show();
            }
        }

