        Set<String> emptyBackup = new HashSet<>();
        Set<String> stringSet = sharedPref.getStringSet(key, emptyBackup);

        if (stringSet != null) {
            Set<Integer> intSet = new HashSet<>(stringSet.size());
            for (String string : stringSet) {
