    public int getIndexOfLastChild(int commentDepth, int pos) {
        int lastChildIndex = pos;
        for (int i = pos + 1; i < comments.size(); i++) {
            if (comments.get(i).depth > commentDepth) {
                lastChildIndex = i;
            } else {
                return lastChildIndex;
            }
        }
        return lastChildIndex;
    }

